input.command:
timeout 100 python3 - <<'EOF'
import math, random

def reconcile(vals, target):
    """Nudge largest-magnitude entry by ulp(target) until plain fold == target."""
    vals = vals[:]
    k = max(range(len(vals)), key=lambda i: abs(vals[i]))
    if target == 0.0:
        step = 1e-100
    else:
        step = math.ulp(target)
    def fold(a):
        s = 0.0
        for i,v in enumerate(vals):
            s += a if i==k else v
        return s
    a = vals[k]
    for nudges in range(100):
        t = fold(a)
        if t == target:
            vals[k] = a
            return vals, nudges, 0.0
        a = math.nextafter(a, math.inf if target > t else -math.inf, step=step)
    return vals, -1, abs(a-vals[k])

random.seed(11)
fails=0; maxn=0; maxadj_rel=0.0; trials=400000
for _ in range(trials):
    P=random.randint(1,15); F=random.randint(1,15)
    lo,hi = random.choice([(-6,9),(-30,30),(-300,300)])
    sens=[[round(random.uniform(-1,1)*10**random.randint(lo,hi),6) for _ in range(F)] for _ in range(P)]
    sh=[round(random.uniform(-1,1)*10**random.randint(lo,hi),6) for _ in range(F)]
    fac=[]
    acc=0.0
    for j in range(F):
        for i in range(P):
            acc += -sens[i][j]*sh[j]
        fac.append(None)
    # uninterrupted factor-major accumulator => canonical loss
    loss=0.0
    fac=[]
    cells_by_f=[[] for _ in range(F)]
    for j in range(F):
        for i in range(P):
            c=-sens[i][j]*sh[j]
            loss+=c
            cells_by_f[j].append(c)
    standalone=[ (lambda L: (lambda s: s)(sum(L)))(L) for L in cells_by_f]
    out,n,adj = reconcile(standalone, loss)
    s=sum(out)
    if n<0 or s!=loss:
        fails+=1
        if fails<=3: print("FAIL", n, s, loss)
    else:
        maxn=max(maxn,n)
        if loss!=0: maxadj_rel=max(maxadj_rel, abs(out[max(range(F),key=lambda i:abs(standalone[i]))]-standalone[max(range(F),key=lambda i:abs(standalone[i]))])/abs(loss))
print(f"trials={trials} fails={fails} max_nudges={maxn} max_adjustment_relative={maxadj_rel:.2e}")
